void deleteByUserAndCourse(User user, Course course);


/**
 * 활성화된 교육과정 목록 조회
 * 
 * @return 활성화된 교육과정 목록
 */
List<Course> findByActiveTrue();


/**
 * 수강생 수 기준 인기 과정 조회 (활성화된 과정만)
 */
List<Course> findByActiveTrueOrderByEnrollmentCountDesc();


/**
 * 최신 과정 조회 (생성일 기준, 활성화된 과정만)
