    this.enabled = false;
}


/**
 * 이메일로 사용자를 조회
 * @param email 조회할 사용자의 이메일
 * @return Optional로 감싼 User 객체
 */
Optional<User> findByEmail(String email);


/**
 * 이메일이 존재하는지 확인
 * @param email 확인할 이메일
 * @return 존재하면 true, 아니면 false
 */
